{"tool":"newFileCreated","path":"src/main/kotlin/set/starlev/config/categories/MusicConfig.kt","content":"package set.starlev.config.categories

import com.google.gson.annotations.Expose
import io.github.notenoughupdates.moulconfig.annotations.Accordion
import io.github.notenoughupdates.moulconfig.annotations.ConfigEditorBoolean
import io.github.notenoughupdates.moulconfig.annotations.ConfigEditorButton
import io.github.notenoughupdates.moulconfig.annotations.ConfigEditorColour
import io.github.notenoughupdates.moulconfig.annotations.ConfigEditorSlider
import io.github.notenoughupdates.moulconfig.annotations.ConfigOption

class MusicConfig {
    @Expose
    @ConfigOption(name = "Визуальная музыка", desc = "Атмосферная музыка из нотных блоков с визуальными эффектами для каждой локации.")
    @Accordion
    var visualMusic = VisualMusicConfig()

    class VisualMusicConfig {
        @Expose
        @ConfigOption(name = "Включить музыку", desc = "Включает систему визуальной музыки по локациям.")
        @ConfigEditorBoolean
        var enabled = true

        @Expose
        @ConfigOption(name = "Громкость", desc = "Общая громкость музыки (0-100%).")
        @ConfigEditorSlider(minValue = 0f, maxValue = 100f, minStep = 1f)
        var volume = 70f

        @Expose
        @ConfigOption(name = "Задержка перед стартом", desc = "Время в секундах перед началом музыки после смены локации (4-7 сек).")
        @ConfigEditorSlider(minValue = 4f, maxValue = 7f, minStep = 1f)
        var startDelay = 5f

        @Expose
        @ConfigOption(name = "Время перехода", desc = "Длительность плавного перехода между треками (сек).")
        @ConfigEditorSlider(minValue = 1f, maxValue = 5f, minStep = 0.5f)
        var fadeDuration = 2f

        @Expose
        @ConfigOption(name = "Визуальные эффекты", desc = "Показывать визуальные ноты и частицы.")
        @ConfigEditorBoolean
        var showVisuals = true

        @Expose
        @ConfigOption(name = "Масштаб частиц", desc = "Размер визуальных нот.")
        @ConfigEditorSlider(minValue = 0.5f, maxValue = 3f, minStep = 0.1f)
        var particleScale = 1.2f

        @Expose
        @ConfigOption(name = "Количество частиц", desc = "Максимальное количество нот на экране.")
        @ConfigEditorSlider(minValue = 5f, maxValue = 50f, minStep = 1f)
        var maxParticles = 25f

        @Expose
        @ConfigOption(name = "🔴 Боевые локации", desc = "Адская крепость, Кладбище, Логово Арахны, Руины и др.")
        @Accordion
        var combat = LocationMusicEntryConfig(
            enabled = true,
            noteColor = "ff:180:30:30",
            tempo = 140,
            intensity = 0.8f
        )

        @Expose
        @ConfigOption(name = "🟡 Фермерские локации", desc = "Амбар, Грибная пустыня, Оазис, Ферма.")
        @Accordion
        var farming = LocationMusicEntryConfig(
            enabled = true,
            noteColor = "ff:255:200:50",
            tempo = 90,
            intensity = 0.4f
        )

        @Expose
        @ConfigOption(name = "🟢 Леснические локации", desc = "Дом викингов, Лес, Джунгли, Саванна и др.")
        @Accordion
        var foraging = LocationMusicEntryConfig(
            enabled = true,
            noteColor = "ff:50:180:50",
            tempo = 100,
            intensity = 0.5f
        )

        @Expose
        @ConfigOption(name = "🔵 Шахтёрские локации", desc = "Гномья кузница, Золотая шахта, Глубокие пещеры и др.")
        @Accordion
        var mining = LocationMusicEntryConfig(
            enabled = true,
            noteColor = "ff:50:100:200",
            tempo = 110,
            intensity = 0.6f
        )

        @Expose
        @ConfigOption(name = "🟣 Эндер локации", desc = "Драконье гнездо, Пустотный склеп, Энд, Убежище Зеалотов.")
        @Accordion
        var ender = LocationMusicEntryConfig(
            enabled = true,
            noteColor = "ff:180:50:200",
            tempo = 80,
            intensity = 0.7f
        )

        @Expose
        @ConfigOption(name = "⚪️ Загадочные локации", desc = "Бездна, Гора, Туман.")
        @Accordion
        var mysterious = LocationMusicEntryConfig(
            enabled = true,
            noteColor = "ff:200:200:220",
            tempo = 70,
            intensity = 0.5f
        )

        @Expose
        @ConfigOption(name = "⚫️ Хаб локации", desc = "Библиотека, Аукцион, Банк, Рынок и др.")
        @Accordion
        var hub = LocationMusicEntryConfig(
            enabled = true,
            noteColor = "ff:150:150:150",
            tempo = 100,
            intensity = 0.3f
        )

        @ConfigOption(name = "Сбросить настройки", desc = "Возвращает все настройки музыки к стандартным.")
        @ConfigEditorButton(buttonText = "Сброс")
        val resetSettings: Runnable = Runnable {
            enabled = true
            volume = 70f
            startDelay = 5f
            fadeDuration = 2f
            showVisuals = true
            particleScale = 1.2f
            maxParticles = 25f
        }

        class LocationMusicEntryConfig(
            enabled: Boolean = true,
            noteColor: String = "ff:255:255:255",
            tempo: Int = 100,
            intensity: Float = 0.5f
        ) {
            @Expose
            @ConfigOption(name = "Включить", desc = "Воспроизводить музыку в этой категории локаций.")
            @ConfigEditorBoolean
            var enabled = enabled

            @Expose
            @ConfigOption(name = "Цвет нот", desc = "Цвет визуальных музыкальных нот.")
            @ConfigEditorColour
            var noteColor = noteColor

            @Expose
            @ConfigOption(name = "Темп (BPM)", desc = "Скорость воспроизведения музыки.")
            @ConfigEditorSlider(minValue = 60f, maxValue = 180f, minStep = 5f)
            var tempo = tempo

            @Expose
            @ConfigOption(name = "Интенсивность", desc = "Насыщенность и сложность мелодии.")
            @ConfigEditorSlider(minValue = 0.1f, maxValue = 1f, minStep = 0.1f)
            var intensity = intensity
        }
    }
