{"tool":"newFileCreated","path":"src/main/kotlin/set/starlev/features/music/LocationMusicEngine.kt","content":"package set.starlev.features.music

import net.minecraft.client.Minecraft
import net.minecraft.core.particles.NoteParticle
import net.minecraft.sounds.SoundEvents
import net.minecraft.sounds.SoundSource
import net.minecraft.world.phys.Vec3
import set.starlev.StarredHeltix
import set.starlev.render.RenderEvents
import set.starlev.utils.ColorUtils
import set.starlev.utils.detectors.LocationDetector
import kotlin.math.cos
import kotlin.math.sin

/**
 * Движок визуальной музыки по локациям.
 * Генерирует мелодии через нотные блоки, управляет переходами и визуальными эффектами.
 */
object LocationMusicEngine {

    private val mc = Minecraft.getInstance()

    // Состояние
    private var currentCategory: LocationMusicCategory? = null
    private var targetCategory: LocationMusicCategory? = null
    private var isPlaying = false
    private var isTransitioning = false

    // Таймеры
    private var lastLocationCheck = 0L
    private var musicStartTime = 0L
    private var transitionStartTime = 0L
    private var lastNoteTime = 0L
    private var lastTickTime = 0L

    // Позиция в мелодии
    private var melodyIndex = 0
    private var harmonyIndex = 0
    private var rhythmIndex = 0
    private var ticksUntilNextNote = 0

    // Fade
    private var currentVolume = 0f
    private var targetVolume = 0f

    // Визуальные частицы
    private val activeParticles = mutableListOf<MusicParticle>()

    // Мелодическая память для вариативности
    private var lastNoteIndex = -1
    private var phrasePosition = 0
    private val phraseLength = 8

    fun init() {
        RenderEvents.register { context ->
            val config = StarredHeltix.feature.music.visualMusic
            if (!config.enabled) {
                stopMusic()
                return@register
            }

            updateLocation()
            if (isPlaying) {
                updateMusic(context)
            }
            if (config.showVisuals) {
                updateParticles(context)
            }
        }
    }

    private fun updateLocation() {
        val now = System.currentTimeMillis()
        if (now - lastLocationCheck < 500) return
        lastLocationCheck = now

        val locationName = LocationDetector.getCurrentLocationClean() ?: return
        val newCategory = LocationMusicCategory.fromLocation(locationName) ?: return

        if (newCategory != currentCategory) {
            switchCategory(newCategory)
        }
    }

    private fun switchCategory(newCategory: LocationMusicCategory) {
        val config = StarredHeltix.feature.music.visualMusic

        // Проверяем, включена ли категория
        val categoryConfig = getCategoryConfig(newCategory)
        if (categoryConfig != null && !categoryConfig.enabled) {
            if (isPlaying) {
                startTransition(null)
            }
            return
        }

        if (currentCategory == null) {
            // Первый запуск
            targetCategory = newCategory
            musicStartTime = System.currentTimeMillis() + (config.startDelay * 1000).toLong()
            isTransitioning = false
        } else if (newCategory != currentCategory) {
            // Смена локации - плавный переход
            startTransition(newCategory)
        }
    }

    private fun startTransition(newCategory: LocationMusicCategory?) {
        val config = StarredHeltix.feature.music.visualMusic
        isTransitioning = true
        transitionStartTime = System.currentTimeMillis()
        targetVolume = 0f
        targetCategory = newCategory

        if (newCategory == null) {
            // Остановка
            currentCategory = null
            isPlaying = false
        }
    }

    private fun updateMusic(context: Any) {
        val config = StarredHeltix.feature.music.visualMusic
        val now = System.currentTimeMillis()

        // Обработка перехода
        if (isTransitioning) {
            val elapsed = (now - transitionStartTime) / 1000f
            val fadeDuration = config.fadeDuration

            if (elapsed >= fadeDuration) {
                // Переход завершён
                isTransitioning = false
                if (targetCategory != null) {
                    currentCategory = targetCategory
                    melodyIndex = 0
                    harmonyIndex = 0
                    rhythmIndex = 0
                    phrasePosition = 0
                    lastNoteIndex = -1
                    musicStartTime = now
                    targetVolume = config.volume / 100f
                    isPlaying = true
                } else {
                    isPlaying = false
                    currentVolume = 0f
                    return
                }
            } else {
                currentVolume = (1f - elapsed / fadeDuration) * (config.volume / 100f)
            }
            return
        }

        // Задержка перед стартом
        if (!isPlaying && targetCategory != null) {
            if (now >= musicStartTime) {
                currentCategory = targetCategory
                isPlaying = true
                targetVolume = config.volume / 100f
                melodyIndex = 0
                harmonyIndex = 0
                rhythmIndex = 0
                phrasePosition = 0
                lastNoteIndex = -1
            }
            return
        }

        if (!isPlaying || currentCategory == null) return

        // Fade in/out к целевой громкости
        val fadeSpeed = 0.05f
        if (currentVolume < targetVolume) {
            currentVolume = minOf(currentVolume + fadeSpeed, targetVolume)
        } else if (currentVolume > targetVolume) {
            currentVolume = maxOf(currentVolume - fadeSpeed, targetVolume)
        }

        if (currentVolume <= 0.01f) return

        // Воспроизведение нот
        val categoryConfig = getCategoryConfig(currentCategory!!)
        val tempo = categoryConfig?.tempo ?: 100
        val intensity = categoryConfig?.intensity ?: 0.5f
        val beatInterval = 60000L / tempo // мс между битами

        if (now - lastNoteTime >= beatInterval * ticksUntilNextNote) {
            playNote(currentCategory!!, intensity, context)
            lastNoteTime = now

            // Следующий ритм
            val rhythm = currentCategory!!.rhythmPattern
            rhythmIndex = (rhythmIndex + 1) % rhythm.size
            ticksUntilNextNote = rhythm[rhythmIndex]

            // Позиция в фразе
            phrasePosition = (phrasePosition + 1) % phraseLength
            if (phrasePosition == 0) {
                // Новая фраза - небольшая вариация
                melodyIndex = (melodyIndex + 1) % currentCategory!!.baseNotes.size
            }
        }
    }

    private fun playNote(category: LocationMusicCategory, intensity: Float, context: Any) {
        val config = StarredHeltix.feature.music.visualMusic
        val player = mc.player ?: return
        val world = mc.level ?: return

        // Выбираем ноту мелодии с вариативностью
        val baseNotes = category.baseNotes
        val harmonyNotes = category.harmonyNotes

        // Умный выбор ноты (избегаем повторов, создаём мелодичность)
        var noteIndex = melodyIndex % baseNotes.size
        if (noteIndex == lastNoteIndex) {
            noteIndex = (noteIndex + 1 + (System.currentTimeMillis() % 3).toInt()) % baseNotes.size
        }
        lastNoteIndex = noteIndex

        val midiNote = baseNotes[noteIndex]
        val pitch = midiToPitch(midiNote)

        // Воспроизводим звук нотного блока
        val volume = currentVolume * 0.3f * intensity
        if (volume > 0.01f) {
            val instrument = selectInstrument(category, phrasePosition)
            val sound = when (instrument) {
                Instrument.HARP -> SoundEvents.NOTE_BLOCK_HARP.value()
                Instrument.BASS -> SoundEvents.NOTE_BLOCK_BASS.value()
                Instrument.BELL -> SoundEvents.NOTE_BLOCK_BELL.value()
                Instrument.FLUTE -> SoundEvents.NOTE_BLOCK_FLUTE.value()
                Instrument.CHIME -> SoundEvents.NOTE_BLOCK_CHIME.value()
                Instrument.PLING -> SoundEvents.NOTE_BLOCK_PLING.value()
            }

            // Звук вокруг игрока
            val pos = player.position()
            world.playLocalSound(
                pos.x + randomOffset(),
                pos.y + 1.5,
                pos.z + randomOffset(),
                sound,
                SoundSource.RECORDS,
                volume,
                pitch,
                false
            )

            // Гармония (с вероятностью на основе интенсивности)
            if (intensity > 0.4f && System.currentTimeMillis() % 3 == 0L) {
                val harmIndex = harmonyIndex % harmonyNotes.size
                val harmNote = harmonyNotes[harmIndex]
                val harmPitch = midiToPitch(harmNote)
                harmonyIndex = (harmonyIndex + 1) % harmonyNotes.size

                world.playLocalSound(
                    pos.x + randomOffset(),
                    pos.y + 2.0,
                    pos.z + randomOffset(),
                    sound,
                    SoundSource.RECORDS,
                    volume * 0.5f,
                    harmPitch,
                    false
                )
            }
        }

        // Визуальная частица
        if (config.showVisuals && activeParticles.size < config.maxParticles.toInt()) {
            spawnParticle(category, midiNote, config)
        }
    }

    private fun spawnParticle(category: LocationMusicCategory, midiNote: Int, config: MusicConfig.VisualMusicConfig) {
        val player = mc.player ?: return
        val categoryConfig = getCategoryConfig(category)
        val colorHex = categoryConfig?.noteColor ?: "ff:255:255:255"
        val color = parseMoulColor(colorHex)

        val scale = config.particleScale
        val atmosphere = category.atmosphere

        val particle = MusicParticle(
            x = player.position().x + randomOffset() * 3,
            y = player.position().y + 1.0 + Math.random() * 2,
            z = player.position().z + randomOffset() * 3,
            color = color,
            scale = scale,
            atmosphere = atmosphere,
            noteHeight = ((midiNote - 33) / 24.0f).coerceIn(0f, 1f),
            lifetime = 60 + (Math.random() * 40).toInt(),
            age = 0
        )

        activeParticles.add(particle)
    }

    private fun updateParticles(context: Any) {
        val player = mc.player ?: return
        val iter = activeParticles.iterator()

        while (iter.hasNext()) {
            val p = iter.next()
            p.age++

            if (p.age >= p.lifetime) {
                iter.remove()
                continue
            }

            // Движение частицы в зависимости от атмосферы
            when (p.atmosphere) {
                AtmosphereType.INTENSE -> {
                    p.x += (Math.random() - 0.5) * 0.15
                    p.y += 0.04
                    p.z += (Math.random() - 0.5) * 0.15
                }
                AtmosphereType.CALM -> {
                    p.x += sin(p.age * 0.05) * 0.02
                    p.y += 0.02
                    p.z += cos(p.age * 0.05) * 0.02
                }
                AtmosphereType.NATURE -> {
                    p.x += sin(p.age * 0.03) * 0.03
                    p.y += 0.025 + sin(p.age * 0.1) * 0.01
                    p.z += cos(p.age * 0.03) * 0.03
                }
                AtmosphereType.DEEP -> {
                    p.x += (Math.random() - 0.5) * 0.05
                    p.y += 0.01
                    p.z += (Math.random() - 0.5) * 0.05
                }
                AtmosphereType.MYSTIC -> {
                    p.x += sin(p.age * 0.08) * 0.06
                    p.y += 0.03
                    p.z += cos(p.age * 0.08) * 0.06
                    // Телепортация
                    if (p.age % 20 == 0) {
                        p.x += (Math.random() - 0.5) * 2
                        p.z += (Math.random() - 0.5) * 2
                    }
                }
                AtmosphereType.ETHEREAL -> {
                    p.x += sin(p.age * 0.02) * 0.04
                    p.y += 0.015
                    p.z += cos(p.age * 0.02) * 0.04
                }
                AtmosphereType.SOCIAL -> {
                    p.x += (Math.random() - 0.5) * 0.03
                    p.y += 0.025
                    p.z += (Math.random() - 0.5) * 0.03
                }
            }

            // Рендер частицы
            val lifeRatio = 1f - p.age.toFloat() / p.lifetime
            val alpha = (lifeRatio * 255).toInt().coerceIn(0, 255)
            val currentScale = p.scale * (0.5f + lifeRatio * 0.5f)

            // Визуальная нота (символ ♪)
            val noteSymbols = listOf("♪", "♫", "♬", "♩")
            val symbol = noteSymbols[(p.age / 10) % noteSymbols.size]

            // Рендер через RenderEvents
            // Используем renderText из RenderContext
        }
    }

    private fun selectInstrument(category: LocationMusicCategory, phrasePos: Int): Instrument {
        return when (category.atmosphere) {
            AtmosphereType.INTENSE -> {
                if (phrasePos % 4 < 2) Instrument.BASS else Instrument.PLING
            }
            AtmosphereType.CALM -> {
                if (phrasePos % 3 == 0) Instrument.FLUTE else Instrument.HARP
            }
            AtmosphereType.NATURE -> {
                when (phrasePos % 4) {
                    0 -> Instrument.FLUTE
                    1 -> Instrument.HARP
                    2 -> Instrument.BELL
                    else -> Instrument.HARP
                }
            }
            AtmosphereType.DEEP -> {
                if (phrasePos % 3 == 0) Instrument.BASS else Instrument.CHIME
            }
            AtmosphereType.MYSTIC -> {
                when (phrasePos % 4) {
                    0 -> Instrument.CHIME
                    1 -> Instrument.BELL
                    2 -> Instrument.PLING
                    else -> Instrument.CHIME
                }
            }
            AtmosphereType.ETHEREAL -> {
                if (phrasePos % 2 == 0) Instrument.BELL else Instrument.CHIME
            }
            AtmosphereType.SOCIAL -> {
                if (phrasePos % 3 == 0) Instrument.HARP else Instrument.FLUTE
            }
        }
    }

    private fun midiToPitch(midiNote: Int): Float {
        // Minecraft pitch: 0.5 = самая низкая, 2.0 = самая высокая
        // MIDI 33 = pitch 0.5, MIDI 57 = pitch 1.0, MIDI 81 = pitch 2.0
        return 2.0f.pow((midiNote - 57) / 12.0f)
    }

    private fun randomOffset(): Double {
        return (Math.random() - 0.5) * 2.0
    }

    private fun parseMoulColor(colorStr: String): Int {
        // Формат MoulConfig: "alpha:r:g:b"
        val parts = colorStr.split(":")
        if (parts.size >= 4) {
            val a = parts[0].toIntOrNull() ?: 255
            val r = parts[1].toIntOrNull() ?: 255
            val g = parts[2].toIntOrNull() ?: 255
            val b = parts[3].toIntOrNull() ?: 255
            return (a shl 24) or (r shl 16) or (g shl 8) or b
        }
        return 0xFFFFFFFF.toInt()
    }

    private fun getCategoryConfig(category: LocationMusicCategory): MusicConfig.VisualMusicConfig.LocationMusicEntryConfig? {
        return when (category) {
            LocationMusicCategory.COMBAT -> StarredHeltix.feature.music.visualMusic.combat
            LocationMusicCategory.FARMING -> StarredHeltix.feature.music.visualMusic.farming
            LocationMusicCategory.FORAGING -> StarredHeltix.feature.music.visualMusic.foraging
            LocationMusicCategory.MINING -> StarredHeltix.feature.music.visualMusic.mining
            LocationMusicCategory.ENDER -> StarredHeltix.feature.music.visualMusic.ender
            LocationMusicCategory.MYSTERIOUS -> StarredHeltix.feature.music.visualMusic.mysterious
            LocationMusicCategory.HUB -> StarredHeltix.feature.music.visualMusic.hub
        }
    }

    private fun stopMusic() {
        if (isPlaying) {
            startTransition(null)
        }
    }

    /**
     * Получить текущую играющую категорию (для HUD).
     */
    fun getCurrentCategory(): LocationMusicCategory? = currentCategory

    /**
     * Проверить, играет ли музыка.
     */
    fun isMusicPlaying(): Boolean = isPlaying && currentVolume > 0.01f

    /**
     * Получить текущую громкость (0-1).
     */
    fun getCurrentVolume(): Float = currentVolume

    private enum class Instrument {
        HARP, BASS, BELL, FLUTE, CHIME, PLING
    }

    private data class MusicParticle(
        var x: Double,
        var y: Double,
        var z: Double,
        val color: Int,
        val scale: Float,
        val atmosphere: AtmosphereType,
        val noteHeight: Float,
        val lifetime: Int,
        var age: Int
    )
}
