class MusicConfig {
    @Expose
    @ConfigOption(name = "Музыка по локациям", desc = "Атмосферная музыка из нотных блоков для каждой локации.")
    @Accordion
    var locationMusic = LocationMusicConfig()

    class LocationMusicConfig {
        @Expose
        @ConfigOption(name = "Включить музыку", desc = "Включает систему музыки по локациям.")
        @ConfigEditorBoolean
        var enabled = true

        @Expose
        @ConfigOption(name = "Громкость", desc = "Общая громкость музыки (0-100%).")
        @ConfigEditorSlider(minValue = 0f, maxValue = 100f, minStep = 1f)
        var volume = 70f

        @Expose
        @ConfigOption(name = "Задержка перед стартом", desc = "Время в секундах перед началом музыки после смены локации (4-7 сек).")
        @ConfigEditorSlider(minValue = 4f, maxValue = 7f, minStep = 1f)
        var startDelay = 5f

        @Expose
        @ConfigOption(name = "Время перехода", desc = "Длительность плавного перехода между треками (сек).")
