        var fadeDuration = 2f

        @Expose
        @ConfigOption(name = "🔴 Боевые локации", desc = "Адская крепость, Кладбище, Логово Арахны, Руины и др.")
        @Accordion
        var combat = LocationMusicEntryConfig().apply {
            tempo = 140
            intensity = 0.8f
        }

        @Expose
        @ConfigOption(name = "🟡 Фермерские локации", desc = "Амбар, Грибная пустыня, Оазис, Ферма.")
        @Accordion
        var farming = LocationMusicEntryConfig().apply {
            tempo = 90
            intensity = 0.4f
        }

        @Expose
        @ConfigOption(name = "🟢 Леснические локации", desc = "Дом викингов, Лес, Джунгли, Саванна и др.")
        @Accordion
        var foraging = LocationMusicEntryConfig().apply {
            tempo = 100
            intensity = 0.5f
        }

        @Expose
        @ConfigOption(name = "🔵 Шахтёрские локации", desc = "Гномья кузница, Золотая шахта, Глубокие пещеры и др.")
        @Accordion
        var mining = LocationMusicEntryConfig().apply {
            tempo = 110
            intensity = 0.6f
        }

        @Expose
        @ConfigOption(name = "🟣 Эндер локации", desc = "Драконье гнездо, Пустотный склеп, Энд, Убежище Зеалотов.")
        @Accordion
        var ender = LocationMusicEntryConfig().apply {
            tempo = 80
            intensity = 0.7f
        }

        @Expose
        @ConfigOption(name = "⚪️ Загадочные локации", desc = "Бездна, Гора, Туман.")
        @Accordion
        var mysterious = LocationMusicEntryConfig().apply {
            tempo = 70
            intensity = 0.5f
        }

        @Expose
        @ConfigOption(name = "⚫️ Хаб локации", desc = "Библиотека, Аукцион, Банк, Рынок и др.")
        @Accordion
        var hub = LocationMusicEntryConfig().apply {
            tempo = 100
            intensity = 0.3f
        }

        @ConfigOption(name = "Сбросить настройки", desc = "Возвращает все настройки музыки к стандартным.")
        @ConfigEditorButton(buttonText = "Сброс")
        val resetSettings: Runnable = Runnable {
            enabled = true
            volume = 70f
            startDelay = 5f
            fadeDuration = 2f
        }

        class LocationMusicEntryConfig {
            @Expose
            @ConfigOption(name = "Включить", desc = "Воспроизводить музыку в этой категории локаций.")
            @ConfigEditorBoolean
            var enabled = true

            @Expose
            @ConfigOption(name = "Темп (BPM)", desc = "Скорость воспроизведения музыки.")
            @ConfigEditorSlider(minValue = 60f, maxValue = 180f, minStep = 5f)
            var tempo = 100

            @Expose
            @ConfigOption(name = "Интенсивность", desc = "Насыщенность и сложность мелодии.")
            @ConfigEditorSlider(minValue = 0.1f, maxValue = 1f, minStep = 0.1f)
            var intensity = 0.5f
        }
    }
}
